  ('novos-profissionais', 'novos-profissionais', 'published', true, '2026-09-02', '{"id":"novos-profissionais","slug":"novos-profissionais","title":"Novos profissionais chegaram ao Instituto","subtitle":"Um convite para reencontrar o essencial.","excerpt":"Sete terapeutas passam a atender no Potala neste mês, trazendo constelação familiar, osteopatia, terapia floral e três abordagens que ainda não existiam na casa.","category":"artigos","author":"Redação Potala","publishedAt":"2026-09-02","readingMinutes":4,"cover":"media/home-travessia.webp","coverAlt":"Paisagem contemplativa que acompanha o texto Novos profissionais chegaram ao Instituto","featured":true,"status":"published","content":[{"id":"novos-profissionais-intro","type":"paragraph","text":"Sete terapeutas passam a atender no Potala neste mês, trazendo constelação familiar, osteopatia, terapia floral e três abordagens que ainda não existiam na casa."},{"id":"novos-profissionais-heading","type":"heading","text":"Um caminho para observar"},{"id":"novos-profissionais-body","type":"paragraph","text":"Cada experiência pode ser lida por muitos ângulos. Este texto abre uma pausa para reconhecer o que já está presente e perceber possibilidades que antes passavam despercebidas."},{"id":"novos-profissionais-quote","type":"quote","text":"Conhecimento ganha sentido quando encontra a experiência."}],"relatedPostIds":["oraculo-de-hoje","borra-de-cafe"],"updatedAt":"2026-09-02T12:00:00.000Z"}'::jsonb),
  ('oraculo-de-hoje', 'oraculo-de-hoje', 'published', false, '2026-09-04', '{"id":"oraculo-de-hoje","slug":"oraculo-de-hoje","title":"Oráculo de hoje: a carta da Ponte","subtitle":"Ideias que acompanham a vida cotidiana.","excerpt":"A Ponte não fala de chegada, e sim da travessia. Ela aparece quando as duas margens já são conhecidas e o que falta é atravessar.","category":"oraculos","author":"Núcleo de Oráculos","publishedAt":"2026-09-04","readingMinutes":2,"cover":"media/journey-inspiracao.webp","coverAlt":"Paisagem contemplativa que acompanha o texto Oráculo de hoje: a carta da Ponte","featured":false,"status":"published","content":[{"id":"oraculo-de-hoje-intro","type":"paragraph","text":"A Ponte não fala de chegada, e sim da travessia. Ela aparece quando as duas margens já são conhecidas e o que falta é atravessar."},{"id":"oraculo-de-hoje-heading","type":"heading","text":"Um caminho para observar"},{"id":"oraculo-de-hoje-body","type":"paragraph","text":"Cada experiência pode ser lida por muitos ângulos. Este texto abre uma pausa para reconhecer o que já está presente e perceber possibilidades que antes passavam despercebidas."},{"id":"oraculo-de-hoje-quote","type":"quote","text":"Conhecimento ganha sentido quando encontra a experiência."}],"relatedPostIds":["novos-profissionais","borra-de-cafe"],"updatedAt":"2026-09-04T12:00:00.000Z"}'::jsonb),
