  ('curso-desenho', 'curso-desenho', 'published', false, '2026-08-21', '{"id":"curso-desenho","slug":"curso-desenho","title":"Desenhar é aprender a olhar","subtitle":"Ideias que acompanham a vida cotidiana.","excerpt":"O curso de desenho do Instituto não começa pela mão. Começa por desmontar o que o olho acha que está vendo — e as vagas da nova turma abrem na segunda.","category":"cursos","author":"Ateliê Potala","publishedAt":"2026-08-21","readingMinutes":5,"cover":"media/journey-quem-somos.webp","coverAlt":"Paisagem contemplativa que acompanha o texto Desenhar é aprender a olhar","featured":false,"status":"published","content":[{"id":"curso-desenho-intro","type":"paragraph","text":"O curso de desenho do Instituto não começa pela mão. Começa por desmontar o que o olho acha que está vendo — e as vagas da nova turma abrem na segunda."},{"id":"curso-desenho-heading","type":"heading","text":"Um caminho para observar"},{"id":"curso-desenho-body","type":"paragraph","text":"Cada experiência pode ser lida por muitos ângulos. Este texto abre uma pausa para reconhecer o que já está presente e perceber possibilidades que antes passavam despercebidas."},{"id":"curso-desenho-quote","type":"quote","text":"Conhecimento ganha sentido quando encontra a experiência."}],"relatedPostIds":["novos-profissionais","oraculo-de-hoje"],"updatedAt":"2026-08-21T12:00:00.000Z"}'::jsonb),
