  ('meditacao-inicio', 'meditacao-inicio', 'published', false, '2026-08-14', '{"id":"meditacao-inicio","slug":"meditacao-inicio","title":"Começar a meditar sem virar outra pessoa","subtitle":"Ideias que acompanham a vida cotidiana.","excerpt":"A pergunta mais frequente da Recepção não é como meditar, e sim por quanto tempo. A resposta honesta desaponta um pouco: menos do que você imagina.","category":"praticas","author":"Grupo de Práticas","publishedAt":"2026-08-14","readingMinutes":6,"cover":"media/atividades-pratica.webp","coverAlt":"Paisagem contemplativa que acompanha o texto Começar a meditar sem virar outra pessoa","featured":false,"status":"published","content":[{"id":"meditacao-inicio-intro","type":"paragraph","text":"A pergunta mais frequente da Recepção não é como meditar, e sim por quanto tempo. A resposta honesta desaponta um pouco: menos do que você imagina."},{"id":"meditacao-inicio-heading","type":"heading","text":"Um caminho para observar"},{"id":"meditacao-inicio-body","type":"paragraph","text":"Cada experiência pode ser lida por muitos ângulos. Este texto abre uma pausa para reconhecer o que já está presente e perceber possibilidades que antes passavam despercebidas."},{"id":"meditacao-inicio-quote","type":"quote","text":"Conhecimento ganha sentido quando encontra a experiência."}],"relatedPostIds":["novos-profissionais","oraculo-de-hoje"],"updatedAt":"2026-08-14T12:00:00.000Z"}'::jsonb),
